// messages.publish: Publish copies of one message and report what the broker did with each
// Generated by `pnpm nx g @app/generators:action messages.publish`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  CopyOutcomeSchema,
  PUBLISH_LIMITS,
  PublishBodySchema,
  PublishHeadersSchema,
  PublishPropsSchema,
  PublishSummarySchema,
} from './publish-types.ts';
import { VhostNameSchema } from './topology-types.ts';

export const MessagesPublishInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  vhost: VhostNameSchema,
  /** '' is the default exchange; the routing key is then the queue name. */
  exchange: z.string().max(PUBLISH_LIMITS.textMax),
  routingKey: z.string().max(PUBLISH_LIMITS.textMax),
  props: PublishPropsSchema,
  headers: PublishHeadersSchema.optional(),
  body: PublishBodySchema,
  copies: z.number().int().min(1).max(PUBLISH_LIMITS.copiesMax).default(1),
  /** Always true (DC-12): a copy no queue takes must come back as a return. `false` is refused. */
  mandatory: z.literal(true).default(true),
  /** Always true (DC-12): a publish runs on a confirm channel. `false` is refused. */
  confirm: z.literal(true).default(true),
  /** Per copy: how long to wait for the broker's confirm. */
  timeoutMs: z
    .number()
    .int()
    .min(PUBLISH_LIMITS.timeoutMsMin)
    .max(PUBLISH_LIMITS.timeoutMsMax)
    .default(PUBLISH_LIMITS.timeoutMsDefault),
});

export const MessagesPublishOutputSchema = z.strictObject({
  /** Every copy of the call, once, in order (I-13). */
  copies: z
    .array(
      z.strictObject({
        index: z.number().int().nonnegative(),
        outcome: CopyOutcomeSchema,
        /**
         * returned: the broker's reply code (`NO_ROUTE`); failed: a contract error code; the rest: a
         * short fixed text. A `timeout` means no confirm in time: the broker may still have routed it.
         */
        reason: z.string().max(PUBLISH_LIMITS.reasonMax).optional(),
      }),
    )
    .max(PUBLISH_LIMITS.copiesMax),
  summary: PublishSummarySchema,
  /** True only when every copy is `confirmed`. A returned or timed-out copy never makes it true. */
  allConfirmed: z.boolean(),
  /** Set when the publish was recorded in the history. */
  historyId: z.string().min(1).max(64).optional(),
  /** False when the history row could not be written; the publish itself still stands (I-13). */
  historyRecorded: z.boolean(),
});

export const messagesPublish = defineAction({
  id: 'messages.publish',
  kind: 'command',
  summary:
    'Publish copies of one message and report what the broker did with each',
  input: MessagesPublishInputSchema,
  output: MessagesPublishOutputSchema,
  permission: 'messages.publish',
  risk: 'medium',
  planning: 'optional',
  audit: 'attempt+outcome',
  target: (input) => ({ connectionId: input.cid, vhost: input.vhost }),
  http: { method: 'POST', path: '/connections/{cid}/messages/publish' },
  cli: { command: 'messages publish' },
  since: '1.0',
});
